  const params = new URLSearchParams({ type: 'server', online: 'true' });
  const res = await fetch(`/api/devices?${params}`);
  if (!res.ok) {
    console.log(`HTTP ${res.status}`);
    return;
  }
  const devices = await res.json();
  console.log(devices.map((d) => d.name).join(', '));
}
main();

